import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph User + Dev Monthly - April 2026","description":"","frontmatter":{"title":"Ceph User + Dev Monthly - April 2026","date":"2026-04-15T00:00:00.000Z","updated":"2026-04-16T00:00:00.000Z","tags":["Ceph","PG autoscaler","RGW","distributed storage","auto tiering"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_User_+_Dev_Monthly_-_April_2026.md","filePath":"posts/2026/Ceph_User_+_Dev_Monthly_-_April_2026.md","lastUpdated":1780459816000}'),l={name:"posts/2026/Ceph_User_+_Dev_Monthly_-_April_2026.md"};function s(i,e,n,c,d,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h2 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h2><p>本次 Ceph 用户与开发者月度会议（2026年4月）涵盖三个主要议题：PG autoscaler 的均匀分配改进、RGW auto tiering 的实践经验与讨论，以及 BlueStore 相关 bug 的排查与 RGW admin 删除对象功能的需求说明。</p><h2 id="议题一-pg-autoscaler-均匀分配问题改进" tabindex="-1">议题一：PG Autoscaler 均匀分配问题改进 <a class="header-anchor" href="#议题一-pg-autoscaler-均匀分配问题改进" aria-label="Permalink to &quot;议题一：PG Autoscaler 均匀分配问题改进&quot;">​</a></h2><h3 id="背景介绍" tabindex="-1">背景介绍 <a class="header-anchor" href="#背景介绍" aria-label="Permalink to &quot;背景介绍&quot;">​</a></h3><p>演讲者 Eric是 RADOS 团队的 co-op 开发者，入职约两个月。本次分享了他在 PG autoscaler 上所做的改进工作。</p><h3 id="问题描述" tabindex="-1">问题描述 <a class="header-anchor" href="#问题描述" aria-label="Permalink to &quot;问题描述&quot;">​</a></h3><p>PG autoscaler 的核心功能是根据各 pool 的数据量自动调整 PG 数量。用户可通过 <code>target_sizeratio</code>（目标容量占比）或 <code>target_size_bytes</code>（目标字节数）进行配置。</p><p><strong>已知 Bug</strong>：当多个 pool 设置了相同的 <code>target_size_ratio</code> 时，autoscaler 并不会为它们分配相同数量的 PG。</p><p><strong>根本原因</strong>：当前实现采用&quot;先到先得&quot;的顺序迭代方式。每处理完一个 pool，就从总 PG 预算中扣除已分配的数量，导致后续 pool 的计算基数不断缩小。</p><p><strong>示例</strong>：假设总预算为 6,000 PGs，三个 pool 各设 <code>target_size_ratio = 0.33</code>：</p><ul><li>Pool 1：1/3 × 6,000 = 2,000，除以 3 副本 ≈ 667，向下取整到 512，实际分配 1,536 PGs</li><li>Pool 2：1/3 × 4,464（剩余预算）≈ 512，仍可分配 1,536 PGs</li><li>Pool 3：1/3 × 2,928（剩余预算）≈ 256，实际分配 768 PGs</li></ul><p>结果三个 pool 分配不均，最后一个 pool 被&quot;饿死&quot;。</p><h3 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to &quot;解决方案&quot;">​</a></h3><p>Eric 将此问题建模为类似**背包问题（Knapsack Problem）**的动态规划优化：</p><ol><li><p><strong>Pool 分组</strong>：将具有相同配置（PG target、replication size、biasbulk、autoscale enabled）的 pool 归为一组，确保同组内所有 pool 向同一方向取整（全部向上或全部向下），保证公平性。</p></li><li><p><strong>全局优化</strong>：初始状态假设所有 pool 均向下取整到最近的 2 的幂次，然后逐组迭代，判断是否可以向上取整（不超出预算），选择总代价（与目标值偏差之和）最小的方案。</p></li><li><p><strong>时间复杂度</strong>：O(n log m)，其中 n 为 pool 数量，m 为总 PG 预算。</p></li></ol><p>该改进已提交 Pull Request，无需用户手动配置，升级后自动生效。</p><h3 id="讨论要点" tabindex="-1">讨论要点 <a class="header-anchor" href="#讨论要点" aria-label="Permalink to &quot;讨论要点&quot;">​</a></h3><p><strong>关于 erasure coding pool 的支持</strong>：与会者 Anscar 询问此方案是否适用于 erasure coded pool。Eric 确认同样适用，因为 pool 大小计算方式一致，只需将副本数替换为 k+m 即可。</p><p><strong>关于 PG 大小 vs PG 数量</strong>：Anscar 提出随着硬盘容量不断增大（如 245TB 的驱动器即将上市），autoscaler 是否应更关注单个 PG 的大小而非每 OSD 的 PG 数量。</p><p>Anthony 补充说明：</p><ul><li>CRUSH algorithm 会保证各 OSD 的 PG 数量与其权重（容量）成比例，大容量 OSD 自然会获得更多 PG。</li><li>J balancer 已经考虑了 PG 大小因素，autoscaler 与 balancer 是相关但不同的组件，不应混淆。</li><li>建议将 <code>mon_target_pg_per_osd</code> 从默认值 100 提升至 200，以给 balancer 更大的工作空间。</li><li>将 balancer 的 <code>max_deviation</code> 从 5 调整为 1，可显著改善混合 OSD 大小集群的均衡效果。</li></ul><p><strong>文档问题</strong>：与会者指出，<code>mon_target_pg_per_osd</code> 的文档不够清晰——在混合 OSD 大小的集群中，该参数究竟是针对哪种 OSD 的平均值？建议补充文档说明。Anthony 请其提交 tracker issue 并tag 他跟进。</p><h2 id="议题二-rgw-auto-tiering-实践与讨论" tabindex="-1">议题二：RGW Auto Tiering 实践与讨论 <a class="header-anchor" href="#议题二-rgw-auto-tiering-实践与讨论" aria-label="Permalink to &quot;议题二：RGW Auto Tiering 实践与讨论&quot;">​</a></h2><h3 id="hetzner-的实践经验" tabindex="-1">Hetzner 的实践经验 <a class="header-anchor" href="#hetzner-的实践经验" aria-label="Permalink to &quot;Hetzner 的实践经验&quot;">​</a></h3><p>来自 Hetzner 的工程师分享了他们在 RGW 中实现 auto tiering 的经验：</p><p><strong>背景</strong>：Hetzner 发现约 13% 的 S3 对象小于 4 KB，这类小对象放在 erasure coded pool 中效率极低。</p><p><strong>分层策略</strong>：</p><ul><li>小于 4 KB 的对象→ NVMe replicated pool</li><li>小于 erasure coding 写放大阈值的对象 → HDD replicated pool</li><li>其余对象 → erasure coded pool</li></ul><p><strong>实现方式</strong>：基于社区 Lua 脚本方案，在上传时根据对象大小自动设置 storage class。</p><p><strong>遇到的问题</strong>：</p><ol><li><p><strong>Storage class 泄露</strong>：客户在 list bucket 时会看到内部使用的 storage class 名称。Hetzner 已开发内部补丁，将对客户展示的 storage class 与内部实际使用的隔离，计划贡献至上游。</p></li><li><p><strong>生命周期策略干扰</strong>：若客户知晓内部 storage class，可自行编写 lifecycle policy 将数据从 HDD 迁移至 NVMe，绕过服务商的管控。目前考虑在 RGW 层面拦截包含受限 storage class 的 lifecycle policy 请求。</p></li><li><p><strong>存量数据迁移</strong>：为解决已有数据的迁移问题，Hetzner 开发了 <code>radosgw-admin object rewrite</code> 命令扩展，支持指定目标 storage class，可根据对象大小批量迁移存量数据。</p></li></ol><h3 id="社区讨论" tabindex="-1">社区讨论 <a class="header-anchor" href="#社区讨论" aria-label="Permalink to &quot;社区讨论&quot;">​</a></h3><p><strong>Philip（另一家服务商）</strong>：也在使用类似方案，主要痛点是按 storage class 统计对象数量和用量，目前通过对象计数方式处理，但不够理想。Casey 补充说上游已有相关 PR，将支持按 storage class 分别统计 bucket 用量并配置配额。</p><p><strong>Frederick 的分析</strong>：Hetzner 的核心需求是：</p><ol><li>对客户隐藏内部 storage class，始终展示标准 storage class</li><li>作为服务商能够设置&quot;管理员级别&quot;的 lifecycle policy，优先级高于客户自定义策略，且客户不可见</li></ol><p><strong>Casey 的回应</strong>：</p><ul><li>全局 lifecycle policy 的主要挑战是扩展性——当前 lifecycle 处理只遍历有策略的 bucket，全局策略需要遍历所有 bucket。</li><li>Storage class 是S3 的用户可控特性，建议区分&quot;用户可见 storage class&quot;与&quot;内部 storage class&quot;，可能需要设计一个新的独立特性，而非在现有 storage class 上打补丁。</li><li>Lua 脚本方案虽然灵活，但局限性明显，不应作为长期解决方案。</li><li>建议将此需求纳入后续用户调查，评估社区对 intelligent tiering 功能的需求程度。</li></ul><p><strong>结论</strong>：该功能对大型 S3 服务商有明确价值，值得设计一个完整的上游特性方案，而非依赖 Lua 脚本的临时方案。</p><h2 id="议题三-bluestore-崩溃-bug-排查" tabindex="-1">议题三：BlueStore 崩溃 Bug 排查 <a class="header-anchor" href="#议题三-bluestore-崩溃-bug-排查" aria-label="Permalink to &quot;议题三：BlueStore 崩溃 Bug 排查&quot;">​</a></h2><p>来自 Hetzner 的 Savan 报告了 Samsung BM7 系列 NVMe 驱动器出现疑似 BlueStore 数据损坏的问题，多块驱动器进入 crash loop。</p><p><strong>排查结论</strong>：</p><ul><li>该问题与 BlueStore elastic shared blobs bug 相关</li><li>19.3.2（dot2）版本中 Proxmox 通过修改默认配置添加了 workaround，但并未包含完整修复</li><li>完整修复在 19.3.4（dot4）版本中才正式合入</li><li>重要提示：该 flag 修复仅对<strong>新创建的 OSD</strong> 生效，已有 OSD 需要重新部署才能受益</li></ul><p><strong>行动项</strong>：建议提交 tracker issue，注明版本信息及复现细节，以便社区跟进。</p><h2 id="议题四-rgw-admin-删除-bucket-内所有对象功能需求" tabindex="-1">议题四：RGW Admin 删除 Bucket 内所有对象功能需求 <a class="header-anchor" href="#议题四-rgw-admin-删除-bucket-内所有对象功能需求" aria-label="Permalink to &quot;议题四：RGW Admin 删除 Bucket 内所有对象功能需求&quot;">​</a></h2><h3 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h3><p>在 Ceph multisite 场景下，Hetzner 仅同步 metadata（用户、bucket 元数据），不同步 bucket 数据。当某集群空间不足时，需要将 bucket 数据从源集群迁移至目标集群，迁移完成后需要清空源集群上该 bucket 的数据，但不能删除 bucket 本身（否则会影响 multisite 元数据同步）。</p><h3 id="现有问题" tabindex="-1">现有问题 <a class="header-anchor" href="#现有问题" aria-label="Permalink to &quot;现有问题&quot;">​</a></h3><p><code>radosgw-admin bucket rm</code> 命令会删除整个 bucket，在 multisite 场景下不可用。</p><h3 id="需求" tabindex="-1">需求 <a class="header-anchor" href="#需求" aria-label="Permalink to &quot;需求&quot;">​</a></h3><p>开发 <code>radosgw-admin bucket rm --objects-only</code>（或类似命令），支持删除 bucket 内所有对象而不删除 bucket 本身。Hetzner 的开发者 Sarahan 已开始相关代码工作，希望将其贡献至上游，避免长期维护私有补丁。</p><h2 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h2><table tabindex="0"><thead><tr><th>负责人</th><th>行动项</th></tr></thead><tbody><tr><td>与会者（Anscar）</td><td>提交 tracker issue，说明 <code>mon_target_pg_per_osd</code> 文档需补充&quot;适用于哪种 OSD&quot;的说明，并 tag Anthony</td></tr><tr><td>Hetzner 团队</td><td>将 storage class 隔离补丁贡献至上游</td></tr><tr><td>Hetzner 团队</td><td>推进 <code>radosgw-admin object rewrite</code> 存储类指定功能的上游合入</td></tr><tr><td>Hetzner 团队（Sarahan）</td><td>推进 bucket 内容删除命令的上游合入</td></tr><tr><td>Savan</td><td>提交 BlueStore elastic shared blobs crash相关 tracker issue</td></tr><tr><td>Casey</td><td>评估 RGW 按 storage class 统计用量 PR 的进展</td></tr><tr><td>社区</td><td>在下次用户调查中加入 intelligent tiering / admin lifecycle policy 需求调研</td></tr></tbody></table>',52)])])}const h=t(l,[["render",s]]);export{g as __pageData,h as default};
